using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.AI;using RoadGunner.Editor;
public static class MeasurePlayable{public static string Main(string label){var l=RoadGunnerLevelAuthoring.Current;var n=NavMesh.CalculateTriangulation();var parents=Enumerable.Range(0,n.vertices.Length).ToArray();Func<int,int> find=null;find=i=>parents[i]==i?i:parents[i]=find(parents[i]);Action<int,int> join=(a,b)=>parents[find(a)]=find(b);var seen=new Dictionary<string,int>();for(int i=0;i<n.vertices.Length;i++){var v=n.vertices[i];var key=Mathf.RoundToInt(v.x*100)+","+Mathf.RoundToInt(v.y*100)+","+Mathf.RoundToInt(v.z*100);if(seen.TryGetValue(key,out int old))join(i,old);else seen[key]=i;}for(int t=0;t<n.indices.Length;t+=3){join(n.indices[t],n.indices[t+1]);join(n.indices[t],n.indices[t+2]);}int nearest=Enumerable.Range(0,n.vertices.Length).OrderBy(i=>(n.vertices[i]-l.playerSpawn.position).sqrMagnitude).First();var vtx=Enumerable.Range(0,n.vertices.Length).Where(i=>find(i)==find(nearest)).Select(i=>n.vertices[i]).ToArray();var b=new Bounds(vtx[0],Vector3.zero);foreach(var p in vtx)b.Encapsulate(p);string result=label+" connected playable NavMesh world X/Z bounds: "+b+"; size="+b.size.x.ToString("F3")+" x "+b.size.z.ToString("F3")+" m; vertices="+vtx.Length+"/"+n.vertices.Length;File.WriteAllText("Documentation/RoadGunner/Wasteland-Restore-2026-10-10/Playable-"+label+".txt",result);return result;}}
